"""Browse all retrieved pairs separately from candidates with actual checks."""
from pathlib import Path
import json
import os
ROOT=Path(os.environ.get('VYNULL_LAB_DIR',Path(__file__).resolve().parent.parent/'lab'))/'library_search_v2'

def page():
 return r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vynull · Match finder</title><style>body{margin:0;background:#0d0e11;color:#eee;font:15px/1.5 system-ui}main{max-width:1180px;margin:auto;padding:32px 24px}a{color:#ffad61}h1{font-size:32px;margin:12px 0}p{color:#aab0bb}label{display:flex;flex-direction:column;gap:6px}select,input,button{background:#15181e;color:#eee;border:1px solid #454c59;border-radius:5px;padding:10px;font:inherit}.filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin:24px 0}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:14px 12px;border-bottom:1px solid #333740;vertical-align:top}th{color:#aaa;font-size:13px}small{display:block;color:#a2a6b0}.watch{color:#ffb36a}.good{color:#8ce0aa}#more{margin-top:24px}#summary{color:#ffad61}.empty{padding:24px 0}</style></head><body><main><a href="/">← Library</a> · <a href="/api/review/auditions?collection=discovery-rounds-v1">All search auditions</a><h1>Find the next mix</h1><p id="summary">Loading the library…</p><p>The loop bridge trials hold an instrumental entry through the handoff and let the new vocal arrive afterward. Listen for the groove and melodic fit. All potential matches also includes pairs that still need an audition.</p><div class="filters"><label>Show<select id="mode"><option value="bridges">Loop bridge trials</option><option value="ready">Vocal + tempo candidates</option><option value="clear">Vocal checks only</option><option value="checked">All checked auditions</option><option value="all">All potential matches</option><option value="watch">Vocal overlap warnings</option></select></label><label>Outgoing song<select id="source"><option value="all">All songs</option></select></label><label>Find artist or song<input id="search" type="search" placeholder="Search the library"></label></div><div id="status" role="status"></div><div class="scroll"><table><thead><tr><th>Outgoing → incoming</th><th>Tempo / section keys</th><th>What is checked</th><th>Listen or try</th></tr></thead><tbody id="rows"></tbody></table></div><button id="more" hidden>SHOW MORE</button></main><script>
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalog,checked=[],allPairs=null,limit=50,visible=[];const byId=new Map(),checkedPairs=new Map();
const title=t=>`${t.artist||'Unknown artist'} — ${t.title}`;
function previewLink(p){return '/api/review/auditions?collection='+encodeURIComponent(p.comparison.collection_id)+'&comparison='+encodeURIComponent(p.comparison.group_id)+'#'+encodeURIComponent(p.preview_id);}
function draw(){const mode=document.getElementById('mode').value,source=document.getElementById('source').value,query=document.getElementById('search').value.toLocaleLowerCase();let rows=mode==='all'?(allPairs||[]).map(r=>checkedPairs.has(r.source+'-'+r.target)?Object.assign({},r,checkedPairs.get(r.source+'-'+r.target)):r):checked.filter(r=>mode==='bridges'?r.structure?.passed&&r.vocal.status==='no_sustained_overlap_detected':mode==='checked'?true:mode==='clear'?r.vocal.status==='no_sustained_overlap_detected':mode==='watch'?r.vocal.status==='vocal_overlap_watch':r.vocal.status==='no_sustained_overlap_detected'&&['timing_supported','tempo_agrees_rhythm_varies'].includes(r.deep.rhythm.state)&&r.deep.harmony.state!=='different_local_keys');rows=rows.filter(r=>(source==='all'||r.source===Number(source))&&(!query||[byId.get(r.source),byId.get(r.target)].some(t=>title(t).toLocaleLowerCase().includes(query))));visible=rows;document.getElementById('status').textContent=rows.length+' '+(mode==='all'?'potential pairs':'auditions')+' match these filters.';document.getElementById('rows').innerHTML=rows.slice(0,limit).map(r=>{const a=byId.get(r.source),b=byId.get(r.target),p=r.preview,v=r.vocal,d=r.deep;return `<tr><td>${esc(title(a))}<small>→ ${esc(title(b))}</small>${p?'<small>'+esc(p.variant)+'</small>':''}</td><td>${a.bpm} → ${b.bpm} BPM<small>Incoming tempo ${((r.tempo_factor-1)*100).toFixed(1)}%</small><small>${esc(p?p.selection.measured_source_key:r.sections[0].source_key)} → ${esc(p?p.selection.measured_target_key:r.sections[0].target_key)}</small></td><td>${v?`<span class="${v.status==='vocal_overlap_watch'?'watch':'good'}">${esc(v.text)}</span><small>${esc(d.rhythm.text)}</small><small>${esc(d.harmony.text)}</small>`:'<span class="watch">Vocals and actual beat alignment unchecked</span><small>Retrieved by local sound, tempo and key similarity.</small>'}</td><td>${p?`<a href="${previewLink(p)}">LISTEN + COMPARE</a>`:`<a href="/api/review/auditions?source=${r.source}&target=${r.target}">TRY THIS PAIR</a>`}</td></tr>`;}).join('')||'<tr><td colspan="4" class="empty">No candidates match these filters. Try another song or choose All potential matches.</td></tr>';document.getElementById('more').hidden=rows.length<=limit;}
async function refresh(){limit=50;if(document.getElementById('mode').value==='all'&&!allPairs){document.getElementById('status').textContent='Loading all potential pairs…';const r=await fetch('/api/review/match-catalog');if(!r.ok)throw Error('Could not load potential matches');allPairs=(await r.json()).pairs;}draw();}
async function start(){const results=await Promise.all([fetch('/api/review/match-catalog?summary=1'),fetch('/api/review/audition-data')]);if(results.some(r=>!r.ok))throw Error('Could not load the match finder');catalog=await results[0].json();const data=await results[1].json();for(const t of catalog.tracks)byId.set(t.id,t);document.getElementById('source').innerHTML='<option value="all">All songs</option>'+catalog.tracks.slice().sort((a,b)=>title(a).localeCompare(title(b))).map(t=>`<option value="${t.id}">${esc(title(t))}${t.search_status!=='ready'?' · needs review':''}</option>`).join('');for(const p of data.previews){const vocal=data.vocal_analysis?.[p.preview_id],deep=data.merge_diagnostics?.[p.preview_id];if(vocal&&deep)checked.push({source:p.selection.source_track,target:p.selection.target_track,tempo_factor:p.selection.target_tempo_factor,preview:p,vocal,deep,structure:data.phrase_analysis?.[p.preview_id]});}checked.sort((a,b)=>{const rank={timing_supported:4,tempo_agrees_rhythm_varies:3,rhythm_uncertain:2};return (rank[b.deep.rhythm.state]||0)-(rank[a.deep.rhythm.state]||0)||a.vocal.simultaneous_vocal_seconds-b.vocal.simultaneous_vocal_seconds;});for(const row of checked){const key=row.source+'-'+row.target;if(!checkedPairs.has(key)||checkedPairs.get(key).vocal.status==='vocal_overlap_watch'&&row.vocal.status==='no_sustained_overlap_detected')checkedPairs.set(key,row);}document.getElementById('summary').textContent=`${catalog.total_tracks} library tracks · ${catalog.ordered_pairs.toLocaleString()} potential directed matches · ${checked.length} vocal-checked auditions`;await refresh();}
for(const id of ['mode','source','search'])document.getElementById(id).addEventListener(id==='search'?'input':'change',()=>refresh().catch(e=>document.getElementById('status').textContent=e.message));document.getElementById('more').addEventListener('click',()=>{limit+=50;draw();});start().catch(e=>document.getElementById('status').textContent=e.message);
</script></body></html>'''.encode()

def serve(handler,route,query):
 if route=='matches':
  payload=page();handler.send_response(200);handler.send_header('Content-Type','text/html; charset=utf-8');handler.send_header('Content-Length',str(len(payload)));handler.end_headers();handler.wfile.write(payload);return True
 if route=='match-catalog':
  path=ROOT/'catalog.json'
  if not path.exists():handler.send(503,{'error':'Library search is still being prepared'});return True
  data=json.loads(path.read_text())
  if query.get('summary',[''])[0]=='1':data={k:v for k,v in data.items() if k!='pairs'}
  else:
   source=query.get('source',[''])[0]
   if source:
    try:ident=int(source)
    except ValueError:handler.send(400,{'error':'Invalid source song'});return True
    data['pairs']=[p for p in data['pairs'] if p['source']==ident]
  handler.send(200,data);return True
 return False
